SELECT TRUNC(usage_events.start_time, 'MONTH') AS "month", COUNT(usage_events.event_id) AS "event_count_count" FROM usage_events INNER JOIN customers ON LPAD(CAST(customers.cust_id AS VARCHAR2), 10, '0') = usage_events.client_no WHERE start_time >= TO_TIMESTAMP('2026-06-01 00:00:00.000000', 'YYYY-MM-DD HH24:MI:SS.FF6') AND start_time < TO_TIMESTAMP('2026-11-01 00:00:00.000000', 'YYYY-MM-DD HH24:MI:SS.FF6') AND customers.status = 'A' GROUP BY TRUNC(usage_events.start_time, 'MONTH') FETCH FIRST 50 ROWS ONLY